<?php
require __DIR__.'/app/bootstrap.php';$u=require_login();$id=(int)($_GET['id']??0);$o=store_order($id);if(!$o||((int)$o['buyer_user_id']!==(int)$u['id']&&(int)$o['seller_user_id']!==(int)$u['id']&&!has_permission('shop.orders.manage',$u))){http_response_code(404);exit('Order not found.');}$items=store_order_items($id);$invoice=function_exists('operations_ensure_invoice')?operations_ensure_invoice($id):null;$shipment=function_exists('operations_row')?operations_row('SELECT * FROM shipments WHERE order_id=?',[$id]):null;
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($o['order_number'])?></title><link rel="stylesheet" href="/assets/themes/landing/base.css?v=240"><link rel="stylesheet" href="/assets/live-commerce-3.4.0.css?v=340"></head><body class="lc-page"><section class="shop-section"><div class="lt-shell" style="max-width:950px"><div class="shop-panel"><span class="order-status"><?=e($o['status'])?></span><h1>Order <?=e($o['order_number'])?></h1><p>Payment: <b><?=e($o['payment_method'])?> / <?=e($o['payment_status'])?></b></p><table class="cart-table"><tr><th>Product</th><th>Qty</th><th>Amount</th><th></th></tr><?php foreach($items as $it):?><tr><td><?=e($it['title'])?><br><small><?=e($it['product_type'])?></small></td><td><?=e($it['quantity'])?></td><td>Rs <?=e(number_format((float)$it['line_total'],0))?></td><td><?php if($it['product_type']==='digital'&&$o['payment_status']==='paid'&&(int)$o['buyer_user_id']===(int)$u['id']):?><a href="/store-download.php?order=<?=e($id)?>&item=<?=e($it['id'])?>">Download</a><?php endif;?></td></tr><?php endforeach;?></table><h3 style="text-align:right">Total: Rs <?=e(number_format((float)$o['grand_total'],0))?></h3><?php if($o['payment_method']==='advance'&&$o['payment_status']!=='paid'&&(int)$o['buyer_user_id']===(int)$u['id']):?><a class="cv-primary-btn" href="/shop-payment.php?order=<?=e($id)?>">Complete Advance Payment</a><?php endif;?><div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:18px"><?php if($invoice):?><a class="cv-primary-btn" href="/commerce-invoice.php?id=<?=e($invoice['id'])?>">Invoice / Receipt</a><?php endif;?><?php if((int)$o['buyer_user_id']===(int)$u['id']):?><a class="cv-secondary-btn" href="/support.php">Support</a><?php if($o['status']!=='cancelled'):?><a class="cv-secondary-btn" href="/dispute.php?order_id=<?=e($id)?>">Open Dispute</a><?php endif;?><?php endif;?></div><?php if($shipment):?><p style="margin-top:16px"><b>Shipment:</b> <?=e($shipment['status'])?><?php if($shipment['tracking_number']):?> · Tracking <?=e($shipment['tracking_number'])?><?php endif;?></p><?php endif;?></div></div></section></body></html>
